function countNeighbors(x, y){
  let count = 0;
  for(let dx=-1; dx<=1; dx++){
    for(let dy=-1; dy<=1; dy++){
      let nx = x+dx;
      let ny = y+dy;
      if(nx<0 || nx>=GRID_W || ny<0 || ny>=GRID_H) count++;
      else if(grid[nx][ny] === 1) count++;
    }
  }
  return count;
}

