function updateGame() {
  player.thrusting = false;
  player.backing = false;

  if (keyIsDown(37)) player.angle -= 0.1;
  if (keyIsDown(39)) player.angle += 0.1;

  if (keyIsDown(38)) {
    player.vx += Math.cos(player.angle) * 0.3;
    player.vy += Math.sin(player.angle) * 0.3;
