  player.vy *= 0.95;

  let steps = 4;
  let dx = player.vx / steps;
  let dy = player.vy / steps;
  for(let i=0; i<steps; i++){
    if(!circleCollidesWall(player.x + dx, player.y, player.r)) {
      player.x += dx;
    } else {
      player.vx = 0;
